process.stdin.resume();
process.stdin.setEncoding('utf-8');
let inputString = '';
let currentLine = 0;
process.stdin.on('data', (inputStd) => {
    inputString += inputStd;
});
process.stdin.on('end', function () {
    inputString = inputString
        .trim()
        .split('\n')
        .map((str) => {
            return str.trim();
        });
    main();
});
function readLine() {
    return inputString[currentLine++];
}
function main() {
    let nums = readLine().split(' ').map(Number);
    let [n, m] = nums; // [2, 5]
    for (let i = n + 1; i <= m; i++) {
        // console.log(i);
        if (isPrime(i) && i !== m) {
            console.log('NO');
            return;
        }
        if (isPrime(i)) {
            if (i === m) {
                // console.log(isPrime(i));
                console.log('YES');
                return;
            }
        }
    }
    console.log('NO');
}

function isPrime(number) {
    if (number <= 1) {
        return false;
    }
    for (let i = 2; i < number; i++) {
        if (number % i === 0) {
            return false;
        }
    }
    return true;
}
